components.css:
:host { --control-md: 36px; --duration-fast: 150ms; --ease-out: cubic-bezier(0, 0, 0.2, 1); --font-sans: "Cola Source Sans 3", "Source Sans Pro", ui-sans-serif, system-ui,
      sans-serif; --leading-tight: 1.25; --primary: #000000; --primary-foreground: #ffffff; --radius-lg: 8px; --space-1-5: 6px; --space-3-5: 14px; --text-sm: 14px; --weight-semibold: 600; }
.button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-1-5);
    min-height: var(--control-md);
    padding: 0 var(--space-3-5);
    border: 1px solid var(--primary);
    border-radius: var(--radius-lg);
    background: var(--primary);
    color: var(--primary-foreground);
    font: var(--weight-semibold) var(--text-sm) / var(--leading-tight)
      var(--font-sans);
    text-align: center;
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    box-shadow: none;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      border-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out),
      box-shadow var(--duration-fast) var(--ease-out);
  }
